head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > M > setSelectedInfo]<br/>컴포넌트에서 아이템들의 선택/해제를 아이템 정보를 가진 객체 배열로 설정합니다.",
    "validation" : [        
        "파라미터 배열에 index 설정이 잘못된 아이템이 있는 경우 해당 아이템 이후의 아이템은 처리되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
            target1.remove();
    }

    // comp 생성
    $c.gcm.createLabel('label="첫번째 아이템만 선택되면 성공"', '', 'label1');
    $c.gcm.createBasicCheckComboBox();
}



scwin.btn_getSelectedInfo_onclick = function (e) {
    let rtn = target1.getSelectedInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("objArray:" +rtn);

    if (rtn) {
        rtn.forEach(function(item, index) {
            wf_body_bottom.getObj("scwin").setReturnValue((index+1)+" 번째 선택된 Item 의 label : " +item.label);
            wf_body_bottom.getObj("scwin").setReturnValue((index+1)+" 번째 선택된 Item 의 checked : " +item.checked);
        });          
    }
};



scwin.btn_setAll_onclick = function (e) {
    target1.setSelectedInfo([{index:0,checked:true}, {index:100,checked:true}, {index:2,checked:true},]);
};
